def ordenar(lista):
    nova = lista[:]
    for i in range(len(nova)):
        pos_menor = i
        for j in range(i + 1, len(nova)):
            if nova[j] < nova[pos_menor]:
                pos_menor = j
        nova[i], nova[pos_menor] = nova[pos_menor], nova[i]
    return nova


