def balanceado(texto):
    par = {")": "(", "]": "[", "}": "{"}
    pilha = []
    for c in texto:
        if c in "([{":
            pilha.append(c)
        elif c in par:
            if not pilha:
                return False
            if pilha.pop() != par[c]:
                return False
    return len(pilha) == 0


