from functools import lru_cache

memo = {}


def fib(n):
    if n in memo:
        return memo[n]
    if n < 2:
        resultado = n
    else:
        resultado = fib(n - 1) + fib(n - 2)
    memo[n] = resultado
    return resultado


@lru_cache(maxsize=None)
def degraus(n):
    if n < 0:
        return 0
    if n == 0:
        return 1
    return degraus(n - 1) + degraus(n - 2) + degraus(n - 3)


print(fib(10))      # deve mostrar 55
print(degraus(4))   # deve mostrar 7

