from collections import deque


def menor_caminho(labirinto):
    for l, linha in enumerate(labirinto):
        for c, casa in enumerate(linha):
            if casa == "S":
                inicio = (l, c)
    distancia = {inicio: 0}
    fila = deque([inicio])
    while fila:
        l, c = fila.popleft()
        if labirinto[l][c] == "E":
            return distancia[(l, c)]
        for dl, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nl, nc = l + dl, c + dc
            if 0 <= nl < len(labirinto) and 0 <= nc < len(labirinto[nl]):
                if labirinto[nl][nc] != "#" and (nl, nc) not in distancia:
                    distancia[(nl, nc)] = distancia[(l, c)] + 1
                    fila.append((nl, nc))
    return -1


labirinto = [
    "S.#",
    "..E",
]
print(menor_caminho(labirinto))  # deve mostrar 3
